const nav=document.querySelector('.nav'),menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.innerHTML=open?'Close <span>×</span>':'Menu <span>+</span>'});document.querySelectorAll('.nav nav a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.innerHTML='Menu <span>+</span>'}));document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.filter.active').classList.remove('active');button.classList.add('active')}));const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,fill:'forwards',easing:'cubic-bezier(.2,.7,.2,1)'});observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.artist-card,.gallery-tile,.commission-panel,.about-card,.tos-list').forEach(el=>{el.style.opacity='0';observer.observe(el)});document.querySelectorAll('[data-profile]').forEach(card=>{const openProfile=()=>window.open(card.dataset.profile,'_blank','noopener');card.addEventListener('click',event=>{if(!event.target.closest('a'))openProfile()});card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openProfile()}});card.addEventListener('pointermove',event=>{if(matchMedia('(hover:hover)').matches){const r=card.getBoundingClientRect(),x=(event.clientX-r.left)/r.width-.5,y=(event.clientY-r.top)/r.height-.5;card.style.setProperty('--tilt-x',`${-y*8}deg`);card.style.setProperty('--tilt-y',`${x*10}deg`)}});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y')})});
